sys_ui_action.client_script_v2:
function onClick(g_form) {
    try {
        if (g_form.getValue('comments') == '') {
            g_form.setMandatory('comments', true);
            g_modal.alert("Please add your comments before closing this task");

            return false; //Abort submission
        } else {

            g_modal.confirm("Please confirm if you want to close the exception task?", function(closedconfirmed) {
                if (closedconfirmed == true) {
                    //g_form.submit('collateral_close_task');
                    g_form.setValue('state', 3, 'Closed Complete');
                    g_form.setValue('assigned_to', g_user.userID);
                    g_form.save().then(function() {
                        g_aw.closeRecord();

                        // --- HBEU Routing Check --- MSSCOLATRL-383
                        var hbeuLocations = [
                            "HBEU OTC",
                            "HBEU OTC CASH",
                            "HBEU REPO"
                        ];

                        var userLocation = (g_form.getValue('managing_location') || '').toString().trim().toUpperCase();
                        var outcome = (g_form.getValue('u_outcome') || '').toString();
                        var treatsSwitch = (g_scratchpad.collateralTreatsSwitch || '').toString().toLowerCase();

                        var isSettmovesOutcome =
                            outcome == "Action required in Treats - Settmoves" ||
                            outcome == "Action required in Treats - Settmoves with New Settlement Date";

                        if (isSettmovesOutcome && ( treatsSwitch == 'false' || hbeuLocations.indexOf(userLocation) === -1)) {
                            setTimeout(function() {
                                var listURL = "/x/hsb11/mss-collateral-core/list/params/list-id/2e21419f1bf36e506ed00e1ad34bcb3c"; // Settmoves List View Export
                                var win = top.window.open(listURL, '_self');
                                win.focus();
                            }, 300);

                        } else if (outcome == "Action required in Treats - Settmoves Manual") {
                            setTimeout(function() {
                                //MSSCOLATRL-383 -added for Treats manual task condition added
                                var listURL = "/x/hsb11/mss-collateral-core/list/params/list-id/2e21419f1bf36e506ed00e1ad34bcb3c"; // Settmoves List View Export
                                var win = top.window.open(listURL, '_self');
                                win.focus();

                            }, 300);

                        } else {
                            setTimeout(function() {

                                var listURL = "/x/hsb11/mss-collateral-core/list/params/list-id/25e6a0771b32ea502ac120a8b04bcb3b"; // OPEN Collateral Task category
                                var win = top.window.open(listURL, '_self');
                                win.focus();

                            }, 300);
                        }
                    });
                } else {
                    return false;
                }
            });
        }
    } catch (e) {
        // Silent fail
    }
}

